"""Normalize one numeric history field in checkpoints generated by our first run.

Only NumPy's numeric scalar/dtype types are allowed while reading these known
locally generated files; unrestricted pickle loading is never used.
"""
import json
from pathlib import Path
import sys
import numpy as np
import torch

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'src'))
import lstm_forecasting as experiment

output=ROOT/'results/lstm'
verification=ROOT/'results/verification'
verification.mkdir(exist_ok=True)
notebook=json.loads((ROOT/'notebooks/03_lstm_colab.ipynb').read_text(encoding='utf-8'))
assert notebook['metadata']['execution_evidence']['all_cells_succeeded']
initial={'execution_evidence':notebook['metadata']['execution_evidence'],
         'original_source_sha256':notebook['metadata']['lstm_source_sha256'],
         'initial_experiment_summary':json.loads((output/'experiment_summary.json').read_text()),
         'initial_selection_freeze':json.loads((output/'selection_freeze.json').read_text()),
         'initial_metrics_sha256':experiment.file_sha256(output/'metrics.csv')}
experiment.dump_json(verification/'lstm_first_execution.json',initial)
records=[]
for path in sorted(output.glob('*/last_checkpoint.pt')):
    best=path.parent/'best_weights.pt'
    weight_hash=experiment.file_sha256(best)
    with torch.serialization.safe_globals([np._core.multiarray.scalar,np.dtype,np.dtypes.Float64DType]):
        checkpoint=torch.load(path,map_location='cpu',weights_only=True)
    checkpoint['history']=json.loads(json.dumps(checkpoint['history']))
    experiment.atomic_torch_save(checkpoint,path)
    reread=torch.load(path,map_location='cpu',weights_only=True)
    assert len(reread['history'])==len(checkpoint['history'])
    assert experiment.file_sha256(best)==weight_hash
    records.append({'dataset':path.parent.name,'selected_weights_unchanged':True,
                    'weight_sha256':weight_hash,'checkpoint_loads_with_weights_only':True,
                    'field_normalized':'training history scalar converted to built-in float'})
assert len(records)==4
experiment.dump_json(verification/'lstm_checkpoint_compatibility_fix.json',records)
print(json.dumps(records,indent=2))
